#[derive(Debug, thiserror::Error)]
pub enum ConfigError {
    #[error("{0}")]
    Message(String),
}

pub fn load_config(raw_timeout: Option<&str>, token: Option<&str>) -> Result<Config, ConfigError> {
    let token = token.ok_or_else(|| ConfigError::Message("missing API token".into()))?;
    let timeout = raw_timeout
        .unwrap_or("30")
        .parse::<u64>()
        .map_err(|err| ConfigError::Message(format!("invalid timeout: {err}")))?;
    Ok(Config::new(token, timeout))
}
```

